command.text:

declare @message nvarchar(4000)
select @message = ''

				&DetailTaxGridShowing;
				&VisibleFieldGridDetailShowing;
select @message as message
return

script.text:

function load$GridVoucherDetail$(g) {
	g.add_itemValueChanged(onChange$GridVoucherDetail$);
	g.add_onResponseComplete(on$GridVoucherDetail$ResponseComplete);
	g.add_commandEvent(on$GridVoucherDetail$ExecuteCommand);
	g.$a = {
		gia_nt_sl: '[gia_nt]:=([gia_nt] == 0 ? ([so_luong] != 0 ? ([tien_nt2]/[so_luong]) : 0) : [gia_nt])',
		gia_sl: '[gia]:=([gia] == 0 ? ([so_luong] != 0 ? ([tien2]/[so_luong]) : 0) : [gia])',

		gia_tg: '[gia]:=[gia_nt]*[$ty_gia]',
		tien_nt2_sl: '[tien_nt2]:=[so_luong]*[gia_nt]',
		tien2_sl: '[tien2]:=[so_luong]*[gia]',
		tien2: '[tien2]:=[tien_nt2]*[$ty_gia]',
		ck_nt: '[ck_nt]:=[tien_nt2]*[tl_ck]/100',
		ck_tg: '[ck]:=[ck_nt]*[$ty_gia]',

		&DetailTaxFomula;

		t_tien_nt2: ['t_tien_nt2', 'tien_nt2', '[loai] != "05"'],
		t_tien2: ['t_tien2', 'tien2', '[loai] != "05"'],
		t_ck_nt: ['t_ck_nt', '([loai] == "05" ? [tien_nt2] : [ck_nt])'],
		t_ck: ['t_ck', '([loai] == "05" ? [tien2] : [ck])'],
		t_thue: '[t_thue]:=([t_tien2] - [t_ck])*[thue_suat]/100',
		t_thue_nt: '[t_thue_nt]:=([t_tien_nt2] - [t_ck_nt])*[thue_suat]/100',

		t_tt: '[t_tt]:=[t_tien2] - [t_ck]+[t_thue]',
		t_tt_nt: '[t_tt_nt]:=[t_tien_nt2] - [t_ck_nt]+[t_thue_nt]'
	};
	udf$Detail$(g);
}
/* <flatten type="Javascript"> */
function dispose$GridVoucherDetail$(g) {
	g.$a = null;
	try {g.remove_commandEvent(on$GridVoucherDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridVoucherDetail$ResponseComplete);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridVoucherDetail$);} catch (ex) {}
}
/* </flatten> */
function onChange$GridVoucherDetail$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 'so_luong':
			g.validExpression(o, [g.$a.tien_nt2_sl, g.$a.tien2, g.$a.ck_nt]);
			on$GridVoucherDetail$AmountChange(o, g, f);
			on$GridVoucherDetail$TaxChange(o, g, f);
			break;
		case 'gia_nt':
			g.validExpression(o, [g.$a.tien_nt2_sl, g.$a.gia_tg, g.$a.tien2, g.$a.ck_nt], null, 'tien_nt2');
			on$GridVoucherDetail$AmountChange(o, g, f);
			on$GridVoucherDetail$TaxChange(o, g, f);
			g.live(o, 'tien_nt2');
			break;
		case 'tien_nt2':
			if (f._calPrice) g.validExpression(o, [g.$a.gia_nt_sl, g.$a.gia_tg]);
			g.validExpression(o, [g.$a.tien2, g.$a.ck_nt]);
			on$GridVoucherDetail$AmountChange(o, g, f);
			on$GridVoucherDetail$TaxChange(o, g, f);
			break;
		case 'gia':
			&DetailTaxValidSalesPrice;
			break;
		case 'tien2':
			if (f._calPrice) g.validExpression(o, [g.$a.gia_sl]);
			&DetailTaxValidSalesAmount;
			break;
		case 'ck_nt':
			g.validExpression(o, [g.$a.ck_tg], [g.$a.t_ck_nt, g.$a.t_ck], [g.$a.t_tt_nt, g.$a.t_tt]);
			on$GridVoucherDetail$TaxChange(o, g, f);
			break;
		case 'ck':
			&DetailTaxValidDiscount;
			break;
		&DetailTaxOnchange;
		default:
			break;
	}
}

function on$GridVoucherDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		case 'AfterRemoveRow':
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterCloneRow':
			g.setItemFieldValue('stt_rec0', e.type.Value, '');
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'Check':
			&DetailTaxExecuteCommandCheckAuthority;
			if (!(g.validRowExpression('stt0', '!([tinh_chat] == "1" && [stt0] == 1)'))) break;
			if (!(g.validRowExpression('dvt', '!([loai] == "08" && [dvt] != "")'))) break;
			break;
		&GridExtraToolbarExecuteCommandScript;
		default:
			break;
	}
}

function on$GridVoucherDetail$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		&DetailTaxResponseComplete;
		case 'GetInvoiceItemType':
			g.setItemGridBehavior(o, [['xu_ly', result[0].Value, null, null],['tinh_chat', result[1].Value, null, null]]);
			on$GridVoucherDetail$AmountChange(o, g, f);
			on$GridVoucherDetail$TaxChange(o, g, f);
			break;
		default:
			break;
	}
}

function on$GridVoucherDetail$RowChange(g, f) {
	&DetailTaxValidRowChange;
}
function on$GridVoucherDetail$TaxChange(o, g, f) {
	&DetailTaxValidTaxChange;
}
/* <flatten type="Javascript"> */
function on$GridVoucherDetail$AmountChange(o, g, f) {g.validExpression(g, null, [g.$a.t_tien_nt2, g.$a.t_tien2, g.$a.t_ck_nt, g.$a.t_ck], [g.$a.t_tt_nt, g.$a.t_tt]);}
function onChange$GridAIDetail$ItemType(o) {
	var g = o.grid, v = o.value;
	g.request(o, 'GetInvoiceItemType', 'GetInvoiceItemType', ['loai']);
	g.setItemGridBehavior(o, [
		['stt0', (v == '08' ? 1 : 0), null, null]
	]);

	if (o.value == '08') {
		g.setItemGridBehavior(o, [
			['dvt', '', null, null],
			['so_luong', 0, null, null],
			['gia_nt', 0, null, null],
			['tien_nt2', 0, null, null],
			['gia', 0, null, null],
			['tien2', 0, null, null],
			['ma_thue', '', null, null],
			['thue_suat', 0, null, null],
			['thue_nt', 0, null, null],
			['thue', 0, null, null],
			['ck_nt', 0, null, null],
			['ck', 0, null, null],
			['tk_thue', '', '', null],
			['ma_kh2', '', '', null],
			['tk_cn', 0, null, null]
		]);
	}
	if (v == '05') {
		g.setItemGridBehavior(o, [
			['tl_ck', 0, null, null],
			['ck', 0, null, null],
			['ck_nt', 0, null, null]
		]);
	}
}
/* </flatten> */

			&GridExtraToolbarScript;

grid.response:
		&DetailTaxGetTaxRate;
		&DetailTaxGetTaxAccount;



if exists(select 1 from dmloaihh where loai = @loai and kind in ('3')) begin
	select rtrim(xu_ly) as xu_ly, rtrim(tinh_chat) as tinh_chat from dmloaihh where loai = @loai and kind in ('3')
	return
end
